export function personalizeQuickReply(content: string, fullName?: string | null): string {
    const cleanName = fullName?.trim() || 'Anh/Chị';
    return content.replace(/\{name\}/g, cleanName);
}

const TOPIC_LABEL_MAP: Record<string, string> = Object.fromEntries(
    SUPPORT_TOPIC_OPTIONS.map(item => [item.value, item.label]),
);

export function formatSupportTopic(topic?: string | null): string {
    if (!topic) return 'Tư vấn chung';
    return TOPIC_LABEL_MAP[topic] ?? topic;
}

