export function formatSupportSource(source: SupportThreadSource): string {
    if (source === 'CUSTOMER_PORTAL') return 'Cổng khách hàng';
    if (source === 'LIVE_WIDGET') return 'Chat trực tuyến';
    return 'Biểu mẫu liên hệ';
}

export function resolveContactHref(contactInfo: string): { href: string; isEmail: boolean } | null {
    const trimmed = contactInfo.trim();
    if (!trimmed) return null;
    if (trimmed.includes('@') && !trimmed.includes(' ')) {
        return {href: `mailto:${trimmed}`, isEmail: true};
    }
    const phone = trimmed.replace(/[^\d+]/g, '');
    if (phone.replace(/\D/g, '').length >= 7) {
        return {href: `tel:${phone}`, isEmail: false};
    }
    return null;
}

export function prioritizeQuickReplies(
    items: readonly SupportQuickReply[],
    threadTopic?: string | null,
): SupportQuickReply[] {
    const rank = (itemTopic?: string | null) => {
        if (threadTopic && itemTopic === threadTopic) return 0;
        if (!itemTopic || itemTopic === 'GENERAL_SUPPORT') return 1;
        return 2;
    };
    return [...items].sort((a, b) => {
        const diff = rank(a.topic) - rank(b.topic);
        return diff !== 0 ? diff : (a.sortOrder ?? 0) - (b.sortOrder ?? 0) || a.id - b.id;
    });
}

export function formatSupportTime(iso?: string | null): string {
    if (!iso) return '—';
    const date = new Date(iso);
    if (Number.isNaN(date.getTime())) return '—';
    const diffSec = Math.max(0, Math.floor((Date.now() - date.getTime()) / 1000));
    if (diffSec < 45) return 'Vừa xong';
    if (diffSec < 3600) return `${Math.floor(diffSec / 60)} phút trước`;
    if (diffSec < 86400) return `${Math.floor(diffSec / 3600)} giờ trước`;
    return date.toLocaleString('vi-VN', {
        hour: '2-digit',
        minute: '2-digit',
        day: '2-digit',
        month: '2-digit',
    });
}
